import { HeroContainer, Hero, TituloHero } from "./style.js";


const HeroPrincipal = () => {
    return (
    <>
        <HeroContainer>
            <Hero></Hero>
            <TituloHero>
                <h1>Nutrition</h1>
                <h3>O Melhor Amigo do Nutricionista</h3>
                <p></p>
                <ButtonHero></ButtonHero>
            </TituloHero>
        </HeroContainer>
    </>
    )
}

export default HeroPrincipal;
